     9	public class MessageService {
    10	    private final List<Message> messages = new ArrayList<>();
    11	    private long nextMessageId = 1;
    12	    private final boolean testMode;
    13	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
    14	    private static final String TEST_EMAIL = "testes@pousadamarealta.com.br";
    15	
    16	    public MessageService(boolean testMode) {
    17	        this.testMode = testMode;
    18	    }
    19	
    20	    public Message sendEmail(String to, String subject, String body) {
    21	        if (!EmailValidator.isValid(to)) {
    22	            Message message = new Message(nextMessageId++, "EMAIL", to, subject, body, MessageStatus.BLOCKED);
    23	            messages.add(message);
    24	            return message;
    25	        }
    26	
    27	        String actualTo = to;
    28	        String actualSubject = subject;
    29	        String actualBody = body;
    30	
    31	        if (testMode) {
    32	            actualTo = TEST_EMAIL;
    33	            actualSubject = "[TESTE] " + subject;
    34	            actualBody = "Destinatário original: " + to + "\n" + body;
    35	        }
    36	
    37	        Message message = new Message(nextMessageId++, "EMAIL", actualTo, actualSubject, actualBody, MessageStatus.SENT);
    38	        messages.add(message);
    39	
    40	        if (!testMode && EmailValidator.isValid(to)) {
    41	            Message archiveCopy = new Message(
    42	                    nextMessageId++,
    43	                    "EMAIL",
    44	                    ARCHIVE_EMAIL,
    45	                    "[Cópia] " + subject,
    46	                    body,
    47	                    MessageStatus.SENT);
    48	            messages.add(archiveCopy);
    49	        }
    50	
    51	        return message;
    52	    }
    53	
    54	    public List<Message> getMessages() {
    55	        return new ArrayList<>(messages);
    56	    }
    57	
    58	    public void clearMessages() {
    59	        messages.clear();
    60	        nextMessageId = 1;
    61	    }
    62	}
