     1	package com.pousada.utils;
     2	
     3	public class EmailValidator {
     4	    public static boolean isValid(String email) {
     5	        if (email == null || email.isEmpty()) {
     6	            return false;
     7	        }
     8	
     9	        int atCount = 0;
    10	        int atIndex = -1;
    11	
    12	        for (int i = 0; i < email.length(); i++) {
    13	            if (email.charAt(i) == '@') {
    14	                atCount++;
    15	                atIndex = i;
    16	            }
    17	        }
    18	
    19	        if (atCount != 1) {
    20	            return false;
    21	        }
    22	
    23	        if (atIndex == 0) {
    24	            return false;
    25	        }
    26	
    27	        String domain = email.substring(atIndex + 1);
    28	        if (domain.isEmpty()) {
    29	            return false;
    30	        }
    31	
    32	        int dotCount = 0;
    33	        for (char c : domain.toCharArray()) {
    34	            if (c == '.') {
    35	                dotCount++;
    36	            }
    37	        }
    38	
    39	        if (dotCount == 0) {
    40	            return false;
    41	        }
    42	
    43	        if (domain.startsWith(".") || domain.endsWith(".")) {
    44	            return false;
    45	        }
    46	
    47	        return true;
    48	    }
    49	}
