    33	            actualSubject = "[TESTE] " + subject;
    34	            actualBody = "Destinatário original: " + to + "\n" + body;
    35	        }
    37	        Message message = new Message(nextMessageId++, "EMAIL", actualTo, actualSubject, actualBody, MessageStatus.SENT);
    38	        messages.add(message);
    40	        if (!testMode && EmailValidator.isValid(to)) {
    41	            Message archiveCopy = new Message(
