    22	    public String generateOccupancyReport(LocalDate date) {
    23	        List<String> lines = new ArrayList<>();
    24	        lines.add("room,type,reservation,check_in,check_out");
    26	        int occupiedCount = 0;
    27	        Map<Integer, Room> rooms = roomService.getAllRooms();
    29	        for (int roomNumber : rooms.keySet()) {
    30	            List<Reservation> reservations = reservationService.getReservationsForRoom(roomNumber, date);
    31	            if (!reservations.isEmpty()) {
    32	                Reservation res = reservations.get(0);
    33	                if (res.getStatus() != ReservationStatus.CANCELLED) {
    34	                    Room room = rooms.get(roomNumber);
    35	                    lines.add(roomNumber + "," + room.getType() + "," + res.getId() + ","
    36	                            + DateUtils.formatDateISO(res.getCheckIn()) + ","
    37	                            + DateUtils.formatDateISO(res.getCheckOut()));
    38	                    occupiedCount++;
    39	                }
    40	            }
    41	        }
    43	        lines.add("total," + occupiedCount + "/" + rooms.size());
    45	        return String.join("\n", lines);
    46	    }
    48	    public String generateRevenueReport(int year, int month) {
    49	        List<String> lines = new ArrayList<>();
    50	        lines.add("reservation,room,check_in,check_out,status,amount");
    52	        BigDecimal totalAmount = BigDecimal.ZERO;
    53	        List<Reservation> reservations = new ArrayList<>(reservationService.getReservationsForMonth(year, month));
    55	        reservations.sort((a, b) -> {
    56	            int dateComp = a.getCheckIn().compareTo(b.getCheckIn());
    57	            if (dateComp != 0) {
    58	                return dateComp;
    59	            }
    60	            return Long.compare(a.getId(), b.getId());
    61	        });
    63	        for (Reservation res : reservations) {
    64	            BigDecimal amount = res.getAmountPaid().subtract(res.getRefund() != null ? res.getRefund() : BigDecimal.ZERO);
    65	            if (amount.signum() > 0) {
    66	                lines.add(res.getId() + "," + res.getRoomNumber() + ","
    67	                        + DateUtils.formatDateISO(res.getCheckIn()) + ","
    68	                        + DateUtils.formatDateISO(res.getCheckOut()) + ","
    69	                        + res.getStatus().toString() + ","
    70	                        + formatAmount(amount));
    71	                totalAmount = totalAmount.add(amount);
    72	            }
    73	        }
    75	        lines.add("total," + formatAmount(totalAmount));
    77	        return String.join("\n", lines);
    78	    }
