     1	package com.pousada.utils;
     3	import com.pousada.models.RatePlan;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     8	public class PriceCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    11	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
    12	    private static final int SCALE = 2;
    14	    public static BigDecimal calculateNightlyRate(LocalDate date, BigDecimal baseRate) {
    15	        if (DateUtils.isHighSeason(date)) {
    16	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(SCALE, ROUNDING_MODE);
    17	        }
    18	        return baseRate.setScale(SCALE, ROUNDING_MODE);
    19	    }
    21	    public static BigDecimal calculateSubtotal(
    22	            LocalDate checkIn,
    23	            LocalDate checkOut,
    24	            BigDecimal nightlyBaseRate) {
    25	        BigDecimal subtotal = BigDecimal.ZERO;
    26	        LocalDate currentDate = checkIn;
    28	        while (currentDate.isBefore(checkOut)) {
    29	            BigDecimal nightRate = calculateNightlyRate(currentDate, nightlyBaseRate);
    30	            subtotal = subtotal.add(nightRate);
    31	            currentDate = currentDate.plusDays(1);
    32	        }
    34	        return subtotal.setScale(SCALE, ROUNDING_MODE);
    35	    }
    37	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    38	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    39	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE).setScale(SCALE, ROUNDING_MODE);
    40	        }
    41	        return BigDecimal.ZERO.setScale(SCALE, ROUNDING_MODE);
    42	    }
    44	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    45	        return subtotal.subtract(discount).setScale(SCALE, ROUNDING_MODE);
    46	    }
    47	}
